import LessonDocument from "./LessonDocument";

const styles = "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&family=Rajdhani:wght@400;500;600;700&display=swap');\n*{box-sizing:border-box;margin:0;padding:0}\n:root{\n  --bg:#0a0c0f;--bg2:#0d1117;--bg3:#111820;\n  --panel:#131a22;--panel2:#1a2332;\n  --b:#1e3a5f;--b2:#0f2540;\n  --g:#00ff88;--g2:#00cc6a;\n  --c:#00d4ff;--y:#ffd700;--o:#ff8c00;\n  --r:#ff3b3b;--p:#9d4edd;--bl:#2979ff;\n  --t:#c8d8e8;--t2:#7a9bb5;--t3:#4a6a85;\n  --mono:'JetBrains Mono',monospace;\n  --sans:'Rajdhani','Segoe UI',sans-serif;\n}\nbody{background:var(--bg);color:var(--t);font-family:var(--mono);font-size:13px;line-height:1.6;overflow-x:hidden}\nbody::before{content:'';position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,255,136,.01) 2px,rgba(0,255,136,.01) 4px);pointer-events:none;z-index:9999}\n.wrap{max-width:1100px;margin:0 auto;padding:20px 16px}\n.panel{background:var(--panel);border:1px solid var(--b2);margin-bottom:14px;overflow:hidden}\n.ph{background:var(--panel2);border-bottom:1px solid var(--b);padding:8px 16px;display:flex;align-items:center;gap:10px}\n.pt{font-family:var(--sans);font-size:13px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--c)}\n.pn{margin-left:auto;font-size:10px;color:var(--t3);letter-spacing:1px}\n.pb{padding:18px 20px}\n@keyframes pulse{0%,100%{box-shadow:0 0 6px var(--g)}50%{box-shadow:0 0 16px var(--g);opacity:.5}}\n/* grid */\n.g2{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\n.g3{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n.g4{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}\n/* concept blocks */\n.cb{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.cbl{border-left:3px solid var(--c)}.cbg{border-left:3px solid var(--g)}.cby{border-left:3px solid var(--y)}.cbp{border-left:3px solid var(--p)}.cbo{border-left:3px solid var(--o)}.cbr{border-left:3px solid var(--r)}\n.cbt{font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px}\n.cbl .cbt{color:var(--c)}.cbg .cbt{color:var(--g)}.cby .cbt{color:var(--y)}.cbp .cbt{color:var(--p)}.cbo .cbt{color:var(--o)}.cbr .cbt{color:var(--r)}\n.ct{color:var(--t);font-size:12.5px;line-height:1.7}\n/* terminal */\n.term{background:#050810;border:1px solid #1a2d45;overflow:hidden}\n.tbar{background:#0d1520;border-bottom:1px solid #1a2d45;padding:7px 14px;display:flex;align-items:center;gap:8px}\n.td{width:10px;height:10px;border-radius:50%}\n.tb{padding:14px 18px;font-size:12px;line-height:1.8}\n.pr{color:var(--g)}.sec{display:block;color:var(--t3);font-size:10px;letter-spacing:2px;text-transform:uppercase;border-top:1px solid #1a2d45;padding-top:10px;margin:10px 0 4px}\n.out{display:block;color:var(--t2)}.ocn{display:block;color:var(--c)}.oyn{display:block;color:var(--y)}.orn{display:block;color:var(--o)}.ogn{display:block;color:var(--g)}.ored{display:block;color:var(--r)}.opu{display:block;color:var(--p)}\n/* info/warn */\n.info{display:flex;gap:8px;padding:8px 12px;background:rgba(0,212,255,.06);border-left:3px solid var(--c);margin:10px 0;font-size:12px;color:var(--t2)}\n.warn{display:flex;gap:8px;padding:8px 12px;background:rgba(255,215,0,.06);border-left:3px solid var(--y);margin:10px 0;font-size:12px;color:var(--t2)}\n.good{display:flex;gap:8px;padding:8px 12px;background:rgba(0,255,136,.06);border-left:3px solid var(--g);margin:10px 0;font-size:12px;color:var(--t2)}\n/* table */\n.tbl{width:100%;border-collapse:collapse;font-size:12px}\n.tbl th{background:var(--panel2);padding:9px 12px;text-align:left;font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:1.5px;text-transform:uppercase;border-bottom:2px solid var(--b);color:var(--c)}\n.tbl td{padding:8px 12px;border-bottom:1px solid var(--b2);color:var(--t2);vertical-align:top;font-size:12px}\n.tbl td:first-child{color:var(--g);font-family:var(--mono)}\n.tbl tr:hover td{background:rgba(255,255,255,.02)}\n/* tags */\n.tag{padding:2px 8px;border-radius:2px;font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;font-family:var(--sans)}\n.tg{background:rgba(0,255,136,.12);color:var(--g);border:1px solid rgba(0,255,136,.3)}\n.tc{background:rgba(0,212,255,.1);color:var(--c);border:1px solid rgba(0,212,255,.3)}\n.ty{background:rgba(255,215,0,.1);color:var(--y);border:1px solid rgba(255,215,0,.3)}\n.tp{background:rgba(157,78,221,.12);color:var(--p);border:1px solid rgba(157,78,221,.3)}\n.to{background:rgba(255,140,0,.1);color:var(--o);border:1px solid rgba(255,140,0,.3)}\n.tr2{background:rgba(255,59,59,.1);color:var(--r);border:1px solid rgba(255,59,59,.3)}\n/* checklist */\n.cl{list-style:none}\n.cl li{padding:7px 0;border-bottom:1px solid var(--b2);font-size:12.5px;display:flex;align-items:flex-start;gap:10px;color:var(--t2)}\n.chk{width:16px;height:16px;min-width:16px;border:1px solid var(--g);background:rgba(0,255,136,.1);display:flex;align-items:center;justify-content:center;font-size:10px;color:var(--g);margin-top:1px}\n/* highlights */\n.hl{color:var(--g);font-weight:600}.hc{color:var(--c)}.hy{color:var(--y)}.ho{color:var(--o)}.hp{color:var(--p)}.hr{color:var(--r)}\n/* div */\n.div{height:1px;background:linear-gradient(to right,transparent,var(--b),transparent);margin:10px 0}\n/* summary / next */\n.sum-card{background:var(--bg3);border:1px solid var(--b2);padding:14px}\n.sc-l{font-family:var(--sans);font-size:10px;letter-spacing:2px;text-transform:uppercase;font-weight:600;color:var(--t3);margin-bottom:6px}\n.sc-v{font-size:12px;color:var(--t);line-height:1.6}\n.nxt{background:linear-gradient(135deg,rgba(0,255,136,.08),rgba(0,212,255,.05));border:1px solid rgba(0,255,136,.3);padding:14px 18px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}\n.nb{background:var(--bg);border:1px solid var(--b);padding:6px 16px;font-size:12px;color:var(--g);cursor:pointer;font-family:var(--mono)}\n.nb:hover{background:rgba(0,255,136,.1);border-color:var(--g)}\n/* perm bits */\n.perm-box{background:var(--bg);border:1px solid var(--b2);padding:16px;overflow-x:auto}\n.perm-row{display:flex;gap:4px;align-items:center;flex-wrap:nowrap;margin-bottom:10px;min-width:600px}\n.pb-bit{width:36px;height:36px;display:flex;align-items:center;justify-content:center;font-family:var(--sans);font-size:13px;font-weight:700;border:1px solid;border-radius:2px}\n.pb-on-r{background:rgba(0,255,136,.15);border-color:rgba(0,255,136,.4);color:var(--g)}\n.pb-on-w{background:rgba(255,215,0,.15);border-color:rgba(255,215,0,.4);color:var(--y)}\n.pb-on-x{background:rgba(0,212,255,.12);border-color:rgba(0,212,255,.4);color:var(--c)}\n.pb-on-s{background:rgba(255,140,0,.15);border-color:rgba(255,140,0,.4);color:var(--o)}\n.pb-off{background:rgba(255,255,255,.04);border-color:var(--b2);color:var(--t3)}\n.pb-sep{width:12px;text-align:center;color:var(--t3);font-size:18px}\n.pb-label{font-family:var(--sans);font-size:10px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--t3);margin-top:4px;text-align:center}\n.perm-col{display:flex;flex-direction:column;align-items:center;gap:0}\n/* inode diagram */\n.inode-box{background:var(--bg);border:2px solid rgba(0,212,255,.4);padding:16px;max-width:600px}\n.ib-title{font-family:var(--sans);font-weight:700;font-size:13px;letter-spacing:2px;text-transform:uppercase;color:var(--c);text-align:center;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid rgba(0,212,255,.2)}\n.ib-field{display:flex;gap:10px;padding:5px 0;border-bottom:1px solid var(--b2);font-size:12px}\n.ib-key{width:160px;min-width:160px;color:var(--t3);font-family:var(--sans);font-weight:600;font-size:11px}\n.ib-val{color:var(--t);flex:1}\n.ib-highlight{color:var(--c)}\n/* fhs tree */\n.fhs{background:var(--bg);border:1px solid var(--b2);padding:16px 20px;font-size:12px;line-height:1;overflow-x:auto}\n.fhs-entry{display:flex;align-items:flex-start;gap:10px;padding:5px 0;border-bottom:1px solid rgba(255,255,255,.03)}\n.fhs-path{min-width:130px;font-family:var(--mono);color:var(--g);font-weight:500;font-size:12px;flex-shrink:0}\n.fhs-tag{flex-shrink:0}\n.fhs-desc{color:var(--t2);font-size:11.5px;flex:1}\n.fhs-sec{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--t3);padding:12px 0 4px;display:block}\n/* lvm diagram */\n.lvm-layer{border:1px solid;padding:10px 14px;text-align:center;margin-bottom:4px}\n.lvm-title{font-family:var(--sans);font-size:12px;font-weight:700;letter-spacing:1px;margin-bottom:4px}\n.lvm-sub{font-size:10.5px;color:var(--t3)}\n.lvm-chips{display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-top:6px}\n.lvm-chip{padding:2px 8px;font-size:10px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);color:var(--t2);border-radius:2px}\n.lvm-arrow{text-align:center;color:var(--t3);font-size:14px;padding:2px 0}\n/* link diagram */\n.link-diagram{background:var(--bg);border:1px solid var(--b2);padding:16px}\n.ld-row{display:flex;gap:14px;align-items:flex-start;flex-wrap:wrap}\n.ld-box{flex:1;min-width:200px;border:1px solid;padding:12px;text-align:center}\n.ld-title{font-family:var(--sans);font-size:12px;font-weight:700;margin-bottom:6px}\n.ld-body{font-size:11px;color:var(--t2);line-height:1.6}\n.ld-arrow{display:flex;align-items:center;justify-content:center;padding:0 8px;color:var(--t3);font-size:18px;align-self:center}\n/* stat bar */\n.sbar-row{display:flex;align-items:center;gap:10px;margin:4px 0;font-size:11px}\n.sbar-lbl{width:120px;min-width:120px;color:var(--t3);font-family:var(--sans);font-size:11px}\n.sbar-bg{flex:1;height:6px;background:rgba(255,255,255,.05);overflow:hidden}\n.sbar-fill{height:100%}\n.sbar-val{width:40px;text-align:right;color:var(--t2);font-size:11px}";
const markup = "<div class=\"wrap\">\n\n<!-- ═══ HEADER ═══ -->\n<div style=\"background:linear-gradient(135deg,#0d1a2e,#0a1520);border:1px solid var(--b);border-top:3px solid var(--g);padding:20px 24px;margin-bottom:16px;position:relative;overflow:hidden\">\n  <div style=\"position:absolute;right:-60px;top:-60px;width:200px;height:200px;background:radial-gradient(circle,rgba(0,255,136,.05),transparent 70%);pointer-events:none\"></div>\n  <div style=\"display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px\">\n    <div>\n      <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px\">\n        <div style=\"width:8px;height:8px;border-radius:50%;background:var(--g);animation:pulse 2s infinite\"></div>\n        <span style=\"font-family:var(--sans);font-size:11px;font-weight:600;letter-spacing:3px;text-transform:uppercase;color:var(--g)\">STEP 03 / MODULE 1 ● ACTIVE</span>\n      </div>\n      <h1 style=\"font-family:var(--sans);font-size:26px;font-weight:700;color:#fff;letter-spacing:1px;line-height:1.2\">Linux <span style=\"color:var(--g)\">File System</span> Architecture</h1>\n      <div style=\"display:flex;flex-wrap:wrap;gap:8px;margin-top:10px\">\n        <span class=\"tag tg\">● Intermediate</span>\n        <span class=\"tag tc\">⊞ FHS Hierarchy</span>\n        <span class=\"tag ty\">⊛ Inodes & Permissions</span>\n        <span class=\"tag tp\">⬡ ext4 Internals</span>\n        <span class=\"tag to\">⊕ LVM & Mounting</span>\n      </div>\n    </div>\n    <div style=\"text-align:right;font-size:11px;color:var(--t3);line-height:1.9;font-family:var(--mono)\">\n      <div>MODULE: <span style=\"color:var(--c)\">fs-arch-03</span></div>\n      <div>FS TYPE: <span style=\"color:var(--c)\">ext4 / xfs / btrfs</span></div>\n      <div>PANELS: <span style=\"color:var(--c)\">13</span></div>\n      <div>PREREQ: <span style=\"color:var(--c)\">Step 01+02 ✓</span></div>\n      <div style=\"margin-top:6px;font-size:10px;color:#1e6a3a\">▓▓▓▓▓▓▓▓▓░ FS MOUNTED</div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 01 — FHS OVERVIEW ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🗂</span><span class=\"pt\">Linux File System Hierarchy Standard (FHS)</span><span class=\"pn\">PANEL 01</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>In Linux, <strong style=\"color:var(--c)\">everything is a file</strong>. Processes, hardware devices, kernel parameters, network sockets — all exposed as files in a unified tree rooted at <code>/</code> (root). There are no drive letters (C:, D:). One tree, multiple storage devices mounted anywhere inside it.</span></div>\n\n    <div class=\"fhs\">\n      <!-- Root -->\n      <div class=\"fhs-entry\" style=\"padding-bottom:8px;border-bottom:2px solid var(--b)\">\n        <div class=\"fhs-path\" style=\"color:var(--y);font-size:14px;font-weight:700\">/</div>\n        <span class=\"tag ty\" style=\"flex-shrink:0\">ROOT</span>\n        <div class=\"fhs-desc\" style=\"color:var(--t)\">The top of the entire filesystem tree. Everything mounts under here. Only root can write directly.</div>\n      </div>\n\n      <span class=\"fhs-sec\">── ESSENTIAL SYSTEM BINARIES & CONFIG ──</span>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/bin</div><span class=\"tag tg fhs-tag\">binaries</span><div class=\"fhs-desc\">Essential user command binaries — ls, cp, mv, cat, bash, ps. Required before /usr is mounted. (Symlink to /usr/bin on modern distros)</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/sbin</div><span class=\"tag tg fhs-tag\">sys-bin</span><div class=\"fhs-desc\">System admin binaries — fdisk, fsck, mount, iptables, ip, ifconfig. Only root should use most of these.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/etc</div><span class=\"tag ty fhs-tag\">config</span><div class=\"fhs-desc\">All system-wide configuration files. Plain text. <strong style=\"color:var(--y)\">The most important directory for admins and auditors.</strong> Never contains binaries.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/etc/passwd</div><span class=\"tag tc fhs-tag\" style=\"font-size:9px\">auth</span><div class=\"fhs-desc\">User account database — username:x:UID:GID:comment:home:shell</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/etc/shadow</div><span class=\"tag tr2 fhs-tag\" style=\"font-size:9px\">secret</span><div class=\"fhs-desc\">Hashed passwords — root readable only. Contains password hash, aging info.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/etc/ssh/</div><span class=\"tag tp fhs-tag\" style=\"font-size:9px\">ssh</span><div class=\"fhs-desc\">SSH server config (sshd_config) and host keys.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/etc/crontab</div><span class=\"tag to fhs-tag\" style=\"font-size:9px\">sched</span><div class=\"fhs-desc\">System-wide scheduled tasks. User crons in /var/spool/cron/.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/etc/sudoers</div><span class=\"tag tr2 fhs-tag\" style=\"font-size:9px\">privesc</span><div class=\"fhs-desc\">Sudo rules — who can run what as root. Misconfiguration = privilege escalation.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/etc/hosts</div><span class=\"tag tc fhs-tag\" style=\"font-size:9px\">dns</span><div class=\"fhs-desc\">Static hostname-to-IP mappings. Checked before DNS.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/etc/fstab</div><span class=\"tag tg fhs-tag\" style=\"font-size:9px\">mount</span><div class=\"fhs-desc\">Filesystem mount table — auto-mounted at boot. Wrong entry = boot failure.</div></div>\n\n      <span class=\"fhs-sec\">── VARIABLE DATA (RUNTIME / LOGS) ──</span>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/var</div><span class=\"tag to fhs-tag\">runtime</span><div class=\"fhs-desc\">Data that changes during operation. Logs, databases, mail spools, package cache, cron jobs.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/var/log/</div><span class=\"tag ty fhs-tag\" style=\"font-size:9px\">audit</span><div class=\"fhs-desc\">All system logs — auth.log, syslog, kern.log, nginx/, apache2/, audit/. Critical for forensics.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/var/www/</div><span class=\"tag tg fhs-tag\" style=\"font-size:9px\">web</span><div class=\"fhs-desc\">Web server document roots by convention (nginx, apache).</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/var/lib/</div><span class=\"tag tc fhs-tag\" style=\"font-size:9px\">db</span><div class=\"fhs-desc\">Application state — MySQL data, Docker volumes, dpkg database.</div></div>\n\n      <span class=\"fhs-sec\">── KERNEL VIRTUAL FILESYSTEMS (RAM, NOT DISK) ──</span>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/proc</div><span class=\"tag tp fhs-tag\">procfs</span><div class=\"fhs-desc\"><strong style=\"color:var(--p)\">Virtual FS</strong> — kernel exposes process info and system state as files. Nothing on disk. Generated on-the-fly by kernel.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/proc/cpuinfo</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">CPU model, cores, flags. Reads from kernel data structures.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/proc/meminfo</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">RAM usage, swap, buffers, cache. Source of truth for free/htop.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/proc/&lt;PID&gt;/</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">Per-process: maps (memory map), fd/ (open files), status, cmdline, environ.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/proc/net/</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">Network state: tcp, tcp6, udp, arp, route tables.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/sys</div><span class=\"tag tp fhs-tag\">sysfs</span><div class=\"fhs-desc\"><strong style=\"color:var(--p)\">Virtual FS</strong> — kernel device tree, hardware topology, driver parameters, cgroups, power management. Write to configure kernel at runtime.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/dev</div><span class=\"tag tc fhs-tag\">devfs</span><div class=\"fhs-desc\">Device files — block devices (disks), char devices (terminals, random). Created by udev on-the-fly as hardware appears.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/dev/sda</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">First SATA/SCSI disk. /dev/sda1 = first partition.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/dev/nvme0n1</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">First NVMe disk. /dev/nvme0n1p1 = first partition.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/dev/null</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">Discard sink — write anything here, it disappears. cmd 2>/dev/null.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/dev/random</div><span class=\"fhs-tag\"></span><div class=\"fhs-desc\">Cryptographically secure random bytes from kernel entropy pool.</div></div>\n      <div class=\"fhs-entry\" style=\"padding-left:16px\"><div class=\"fhs-path\" style=\"color:var(--t2)\">/dev/mem</div><span class=\"tag tr2 fhs-tag\" style=\"font-size:9px\">risk</span><div class=\"fhs-desc\">Physical memory device — dangerous. Attackers use this for kernel memory reads.</div></div>\n\n      <span class=\"fhs-sec\">── USER & RUNTIME DATA ──</span>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/home</div><span class=\"tag tg fhs-tag\">users</span><div class=\"fhs-desc\">Home directories for regular users — /home/alice, /home/bob. Users own their home. Root's home is /root.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/root</div><span class=\"tag tr2 fhs-tag\">root</span><div class=\"fhs-desc\">Home directory of the root user. Separate from /home for availability even if /home is unmounted.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/tmp</div><span class=\"tag to fhs-tag\">temp</span><div class=\"fhs-desc\">Temporary files — world-writable, sticky bit set. Cleared on reboot (or by tmpfiles.d). Attack surface: insecure temp file creation.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/run</div><span class=\"tag tc fhs-tag\">runtime</span><div class=\"fhs-desc\">Runtime data since last boot — PID files, sockets (/run/docker.sock), lock files. tmpfs: lives in RAM only.</div></div>\n\n      <span class=\"fhs-sec\">── SHARED RESOURCES & BOOT ──</span>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/usr</div><span class=\"tag tg fhs-tag\">usr</span><div class=\"fhs-desc\">Unix System Resources — bulk of installed software. /usr/bin (user commands), /usr/lib (libraries), /usr/share (data), /usr/local (admin-installed).</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/lib</div><span class=\"tag tc fhs-tag\">libs</span><div class=\"fhs-desc\">Essential shared libraries — glibc (libc.so.6), kernel modules (/lib/modules/). Needed to boot before /usr mounts.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/boot</div><span class=\"tag ty fhs-tag\">boot</span><div class=\"fhs-desc\">Boot files — vmlinuz (kernel), initrd.img (initramfs), grub/ config. Keep separate partition: survives root FS corruption.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/opt</div><span class=\"tag tg fhs-tag\">optional</span><div class=\"fhs-desc\">Optional third-party software — /opt/google/chrome, /opt/splunk. Self-contained installs not managed by package manager.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/srv</div><span class=\"tag tc fhs-tag\">service</span><div class=\"fhs-desc\">Service data — /srv/http (web), /srv/ftp. Conventional location for served data.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/mnt</div><span class=\"tag to fhs-tag\">mount</span><div class=\"fhs-desc\">Temporary mount point — admin mounts external drives, NFS, ISOs here manually.</div></div>\n      <div class=\"fhs-entry\"><div class=\"fhs-path\">/media</div><span class=\"tag tg fhs-tag\">media</span><div class=\"fhs-desc\">Auto-mounted removable media — USB sticks, DVDs, auto-mounted by desktop environments.</div></div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 02 — INODES ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔢</span><span class=\"pt\">Inodes — The Metadata Engine of Linux</span><span class=\"pn\">PANEL 02</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span>Every file and directory has an <strong style=\"color:var(--c)\">inode</strong> — a fixed-size data structure on disk storing all file metadata. The inode does <strong>NOT</strong> store the filename. Filenames live in directory entries (dentries) which map name → inode number. This separation enables hard links.</span></div>\n\n    <div style=\"display:flex;gap:14px;flex-wrap:wrap;margin-bottom:14px\">\n      <div class=\"inode-box\">\n        <div class=\"ib-title\">📋 Inode Structure — /etc/passwd (inode #924673)</div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Inode Number</span><span class=\"ib-val ib-highlight\">924673</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">File Type</span><span class=\"ib-val\">Regular file (-)</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Permissions</span><span class=\"ib-val\" style=\"color:var(--g)\">0644 (rw-r--r--)</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Owner UID</span><span class=\"ib-val\">0 (root)</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Owner GID</span><span class=\"ib-val\">0 (root)</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Hard Link Count</span><span class=\"ib-val ib-highlight\">1</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">File Size</span><span class=\"ib-val\">1872 bytes</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Block Size</span><span class=\"ib-val\">4096 bytes</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Block Count</span><span class=\"ib-val\">8 blocks (on disk)</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">atime (access)</span><span class=\"ib-val\">2026-05-03 09:12:44</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">mtime (modify)</span><span class=\"ib-val\">2026-04-11 14:22:01</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">ctime (inode change)</span><span class=\"ib-val\">2026-04-11 14:22:01</span></div>\n        <div class=\"ib-field\"><span class=\"ib-key\">Data Block Ptrs</span><span class=\"ib-val ib-highlight\">12 direct + 1 indirect + 1 dbl-indirect</span></div>\n        <div class=\"ib-field\" style=\"border-bottom:none\"><span class=\"ib-key\">Filename stored?</span><span class=\"ib-val\" style=\"color:var(--r)\">❌ NO — stored in directory entry</span></div>\n      </div>\n\n      <!-- block pointer diagram -->\n      <div style=\"flex:1;min-width:200px;display:flex;flex-direction:column;gap:10px\">\n        <div class=\"cb cbl\">\n          <div class=\"cbt\">ext4 Block Pointer Scheme</div>\n          <div class=\"ct\">\n            <span class=\"hl\">12 Direct pointers</span> → point directly to data blocks (covers 12×4KB = 48KB)<br><br>\n            <span class=\"hc\">1 Indirect pointer</span> → points to a block of pointers (1024 ptrs × 4KB = 4MB more)<br><br>\n            <span class=\"hy\">1 Double-indirect</span> → pointer → block of ptrs → data (4GB range)<br><br>\n            <span class=\"hp\">1 Triple-indirect</span> → adds TB-scale reach<br><br>\n            Modern ext4 uses <span class=\"hl\">extents</span> instead — contiguous block ranges for efficiency. Large files: one extent describes millions of contiguous blocks.\n          </div>\n        </div>\n        <div class=\"cb cby\">\n          <div class=\"cbt\">Inode Table Facts</div>\n          <div class=\"ct\" style=\"font-size:12px\">\n            Fixed count at <span class=\"hy\">mkfs time</span> — you can run out of inodes before disk space!<br><br>\n            Check: <code style=\"color:var(--c)\">df -i</code><br>\n            Running out of inodes = cannot create new files even with free space.<br><br>\n            Inode size: typically <span class=\"hl\">256 bytes</span> in ext4. Total inodes = partition size ÷ bytes-per-inode ratio.\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Inode inspection commands</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── VIEW INODE OF A FILE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">stat /etc/passwd</span></span>\n        <span class=\"out\">  File: /etc/passwd</span>\n        <span class=\"ocn\">  Size: 1872      Blocks: 8       IO Block: 4096  regular file</span>\n        <span class=\"out\">Device: 802h/2050d  Inode: 924673   Links: 1</span>\n        <span class=\"oyn\">Access: (0644/-rw-r--r--)  Uid: (0/root)   Gid: (0/root)</span>\n        <span class=\"out\">Access: 2026-05-03 09:12:44.821</span>\n        <span class=\"out\">Modify: 2026-04-11 14:22:01.004</span>\n        <span class=\"out\">Change: 2026-04-11 14:22:01.004</span>\n        <span class=\"sec\">──── SHOW INODE NUMBER (ls -i) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ls -i /etc/passwd /etc/shadow /etc/sudoers</span></span>\n        <span class=\"ogn\"> 924673 /etc/passwd</span>\n        <span class=\"ored\"> 924674 /etc/shadow</span>\n        <span class=\"oyn\"> 924680 /etc/sudoers</span>\n        <span class=\"sec\">──── CHECK INODE USAGE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">df -i /</span></span>\n        <span class=\"out\">Filesystem      Inodes  IUsed   IFree IUse% Mounted on</span>\n        <span class=\"ocn\">/dev/nvme0n1p2 3932160 184291 3747869    5% /</span>\n        <span class=\"sec\">──── FIND FILE BY INODE NUMBER ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">find / -inum 924673 2>/dev/null</span></span>\n        <span class=\"ogn\">/etc/passwd</span>\n        <span class=\"out\"># Useful in forensics to find all names pointing to same inode</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 03 — PERMISSIONS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔐</span><span class=\"pt\">File Permissions — rwx Model, chmod, chown, umask</span><span class=\"pn\">PANEL 03</span></div>\n  <div class=\"pb\">\n\n    <!-- Permission bit visual -->\n    <div style=\"font-family:var(--sans);font-size:11px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">Permission String Breakdown — Example: -rwxr-xr-- (0754)</div>\n    <div class=\"perm-box\">\n      <div class=\"perm-row\">\n        <!-- type -->\n        <div class=\"perm-col\">\n          <div class=\"pb-bit\" style=\"background:rgba(255,215,0,.1);border-color:rgba(255,215,0,.4);color:var(--y);width:36px\">-</div>\n          <div class=\"pb-label\">type</div>\n        </div>\n        <div class=\"pb-sep\"></div>\n        <!-- owner -->\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-r\">r</div><div class=\"pb-label\">owner</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-w\">w</div><div class=\"pb-label\">owner</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-x\">x</div><div class=\"pb-label\">owner</div></div>\n        <div class=\"pb-sep\">│</div>\n        <!-- group -->\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-r\">r</div><div class=\"pb-label\">group</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-off\">-</div><div class=\"pb-label\">group</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-x\">x</div><div class=\"pb-label\">group</div></div>\n        <div class=\"pb-sep\">│</div>\n        <!-- other -->\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-r\">r</div><div class=\"pb-label\">other</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-off\">-</div><div class=\"pb-label\">other</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-off\">-</div><div class=\"pb-label\">other</div></div>\n        <div class=\"pb-sep\"></div>\n        <!-- octal -->\n        <div class=\"perm-col\">\n          <div class=\"pb-bit\" style=\"background:rgba(255,215,0,.1);border-color:rgba(255,215,0,.4);color:var(--y);width:44px;font-size:15px\">754</div>\n          <div class=\"pb-label\">octal</div>\n        </div>\n      </div>\n      <!-- second example - SUID -->\n      <div style=\"font-family:var(--sans);font-size:10px;color:var(--t3);letter-spacing:1px;text-transform:uppercase;margin:10px 0 6px\">Special Bits — SUID / SGID / Sticky</div>\n      <div class=\"perm-row\">\n        <div class=\"perm-col\"><div class=\"pb-bit pb-off\">-</div><div class=\"pb-label\">type</div></div>\n        <div class=\"pb-sep\"></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-r\">r</div><div class=\"pb-label\">owner</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-w\">w</div><div class=\"pb-label\">owner</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-s\">s</div><div class=\"pb-label\">SUID</div></div>\n        <div class=\"pb-sep\">│</div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-r\">r</div><div class=\"pb-label\">group</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-off\">-</div><div class=\"pb-label\">group</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-x\">x</div><div class=\"pb-label\">group</div></div>\n        <div class=\"pb-sep\">│</div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-r\">r</div><div class=\"pb-label\">other</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-off\">-</div><div class=\"pb-label\">other</div></div>\n        <div class=\"perm-col\"><div class=\"pb-bit pb-on-x\">x</div><div class=\"pb-label\">other</div></div>\n        <div class=\"pb-sep\"></div>\n        <div class=\"perm-col\"><div class=\"pb-bit\" style=\"background:rgba(255,140,0,.15);border-color:rgba(255,140,0,.4);color:var(--o);width:44px;font-size:15px\">4755</div><div class=\"pb-label\" style=\"color:var(--o)\">SUID</div></div>\n      </div>\n    </div>\n\n    <!-- Permission meaning table -->\n    <table class=\"tbl\" style=\"margin:14px 0\">\n      <thead><tr><th>Bit</th><th>On File</th><th>On Directory</th><th>Octal</th><th>Security Note</th></tr></thead>\n      <tbody>\n        <tr><td>r (read)</td><td style=\"color:var(--t2)\">Read file contents</td><td style=\"color:var(--t2)\">List directory (ls)</td><td style=\"color:var(--g)\">4</td><td style=\"color:var(--t2)\">Safe to grant broadly</td></tr>\n        <tr><td>w (write)</td><td style=\"color:var(--t2)\">Modify file contents</td><td style=\"color:var(--t2)\">Create/delete files inside</td><td style=\"color:var(--y)\">2</td><td style=\"color:var(--r);font-size:11px\">Dir write = delete any file inside, even if file is read-only!</td></tr>\n        <tr><td>x (execute)</td><td style=\"color:var(--t2)\">Execute as program</td><td style=\"color:var(--t2)\">Enter directory (cd)</td><td style=\"color:var(--g)\">1</td><td style=\"color:var(--t2)\">Need x on all dirs in path to access file</td></tr>\n        <tr><td>s (SUID)</td><td style=\"color:var(--o)\">Run as file OWNER (not caller)</td><td style=\"color:var(--t2)\">New files inherit group (SGID)</td><td style=\"color:var(--o)\">4000/2000</td><td style=\"color:var(--r);font-size:11px\">SUID root = runs as root! Audit carefully: find / -perm -4000</td></tr>\n        <tr><td>t (sticky)</td><td style=\"color:var(--t3)\">No effect (historically)</td><td style=\"color:var(--t2)\">Only owner can delete their files</td><td style=\"color:var(--p)\">1000</td><td style=\"color:var(--t2)\">/tmp has sticky bit — prevents users deleting each other's files</td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">chmod · chown · umask · ACL</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── chmod — CHANGE PERMISSIONS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chmod 750 /opt/myapp/config.py</span></span>\n        <span class=\"out\"># owner=rwx(7), group=r-x(5), other=---(0)</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chmod u+x,g-w,o-rwx script.sh   # symbolic mode</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chmod -R 755 /var/www/html/       # recursive</span></span>\n        <span class=\"sec\">──── chown — CHANGE OWNER ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chown www-data:www-data /var/www/html/</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chown -R deploy:devops /opt/myapp/</span></span>\n        <span class=\"sec\">──── umask — DEFAULT PERMISSION MASK ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">umask</span></span>\n        <span class=\"out\">0022</span>\n        <span class=\"ocn\"># New files:  666 - 022 = 644 (rw-r--r--)</span>\n        <span class=\"ocn\"># New dirs:   777 - 022 = 755 (rwxr-xr-x)</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">umask 027   # more restrictive: 640 files, 750 dirs</span></span>\n        <span class=\"sec\">──── ACL — EXTENDED ACCESS CONTROL ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">setfacl -m u:alice:rw /var/data/report.csv</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">getfacl /var/data/report.csv</span></span>\n        <span class=\"out\">file: report.csv</span>\n        <span class=\"out\">owner: root</span>\n        <span class=\"out\">group: sysadmin</span>\n        <span class=\"ocn\">user::rw-</span>\n        <span class=\"ogn\">user:alice:rw-       # alice has read+write via ACL</span>\n        <span class=\"out\">group::r--</span>\n        <span class=\"out\">mask::rw-</span>\n        <span class=\"out\">other::---</span>\n        <span class=\"sec\">──── SUID AUDIT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">find / -perm /4000 -type f -ls 2>/dev/null</span></span>\n        <span class=\"oyn\">924812 44 -rwsr-xr-x 1 root root 44784 /usr/bin/sudo</span>\n        <span class=\"oyn\">924901 32 -rwsr-xr-x 1 root root 30888 /usr/bin/passwd</span>\n        <span class=\"ored\">985124 12 -rwsr-xr-x 1 root root 11032 /tmp/suspicious   ← INVESTIGATE</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 04 — HARD & SOFT LINKS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔗</span><span class=\"pt\">Hard Links vs Symbolic Links</span><span class=\"pn\">PANEL 04</span></div>\n  <div class=\"pb\">\n    <div class=\"link-diagram\">\n      <div class=\"ld-row\">\n        <!-- hard link -->\n        <div style=\"flex:1;min-width:220px\">\n          <div style=\"font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--g);margin-bottom:10px;text-align:center\">HARD LINK</div>\n          <div style=\"display:flex;flex-direction:column;gap:6px;align-items:center\">\n            <div style=\"display:flex;gap:8px;flex-wrap:wrap;justify-content:center\">\n              <div class=\"ld-box\" style=\"border-color:rgba(0,255,136,.4);background:rgba(0,255,136,.07)\">\n                <div class=\"ld-title\" style=\"color:var(--g)\">/etc/passwd</div>\n                <div class=\"ld-body\">directory entry<br>name → inode 924673</div>\n              </div>\n              <div class=\"ld-box\" style=\"border-color:rgba(0,255,136,.4);background:rgba(0,255,136,.07)\">\n                <div class=\"ld-title\" style=\"color:var(--g)\">/backup/passwd.bak</div>\n                <div class=\"ld-body\">directory entry<br>name → inode 924673</div>\n              </div>\n            </div>\n            <div style=\"color:var(--t3);font-size:18px\">↓ ↓</div>\n            <div class=\"ld-box\" style=\"border-color:rgba(255,215,0,.5);background:rgba(255,215,0,.08);width:180px\">\n              <div class=\"ld-title\" style=\"color:var(--y)\">Inode 924673</div>\n              <div class=\"ld-body\">link count: 2<br>actual file data<br>1872 bytes</div>\n            </div>\n          </div>\n          <div class=\"good\" style=\"margin-top:10px;font-size:11px\"><span style=\"color:var(--g);flex-shrink:0\">✓</span>Deleting one name doesn't delete the file — data survives until link count = 0</div>\n        </div>\n\n        <div style=\"padding:0 14px;display:flex;align-items:center;color:var(--t3);font-size:24px\">│</div>\n\n        <!-- soft link -->\n        <div style=\"flex:1;min-width:220px\">\n          <div style=\"font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--c);margin-bottom:10px;text-align:center\">SYMBOLIC LINK (SYMLINK)</div>\n          <div style=\"display:flex;flex-direction:column;gap:6px;align-items:center\">\n            <div class=\"ld-box\" style=\"border-color:rgba(0,212,255,.4);background:rgba(0,212,255,.07);width:200px\">\n              <div class=\"ld-title\" style=\"color:var(--c)\">/usr/bin/python</div>\n              <div class=\"ld-body\">inode 10042<br>type: symlink (l)<br>content: \"/usr/bin/python3\"</div>\n            </div>\n            <div style=\"color:var(--t3);font-size:18px\">↓ follows path</div>\n            <div class=\"ld-box\" style=\"border-color:rgba(0,255,136,.4);background:rgba(0,255,136,.07);width:200px\">\n              <div class=\"ld-title\" style=\"color:var(--g)\">/usr/bin/python3</div>\n              <div class=\"ld-body\">inode 924500<br>real file — binary<br>5.2 MB</div>\n            </div>\n          </div>\n          <div class=\"warn\" style=\"margin-top:10px;font-size:11px\"><span style=\"color:var(--y);flex-shrink:0\">⚠</span>If target is deleted, symlink becomes a \"dangling link\" — still exists, points to nothing</div>\n        </div>\n      </div>\n    </div>\n\n    <table class=\"tbl\" style=\"margin-top:14px\">\n      <thead><tr><th>Property</th><th>Hard Link</th><th>Symbolic Link</th></tr></thead>\n      <tbody>\n        <tr><td>Inode</td><td style=\"color:var(--g)\">Same inode as original</td><td style=\"color:var(--c)\">Different inode (stores path string)</td></tr>\n        <tr><td>Cross-filesystem</td><td style=\"color:var(--r)\">❌ Cannot span different mount points</td><td style=\"color:var(--g)\">✓ Can point anywhere</td></tr>\n        <tr><td>Points to directories</td><td style=\"color:var(--r)\">❌ Not allowed (prevents loops)</td><td style=\"color:var(--g)\">✓ Allowed</td></tr>\n        <tr><td>Survives target deletion</td><td style=\"color:var(--g)\">✓ Data survives (link count > 0)</td><td style=\"color:var(--r)\">❌ Becomes dangling link</td></tr>\n        <tr><td>File type in ls -l</td><td style=\"color:var(--t2)\">Same as original (-)</td><td style=\"color:var(--c)\">l (lrwxrwxrwx)</td></tr>\n        <tr><td>Create command</td><td style=\"color:var(--g)\">ln source link</td><td style=\"color:var(--c)\">ln -s target link</td></tr>\n        <tr><td>Security risk</td><td style=\"color:var(--t2)\">Low — same file</td><td style=\"color:var(--r)\">Symlink attack: /tmp race conditions, path traversal</td></tr>\n      </tbody>\n    </table>\n\n    <div class=\"term\" style=\"margin-top:14px\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Link operations</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── HARD LINK ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ln /etc/passwd /backup/passwd.hardlink</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ls -li /etc/passwd /backup/passwd.hardlink</span></span>\n        <span class=\"ogn\">924673 -rw-r--r-- 2 root root 1872 /etc/passwd</span>\n        <span class=\"ogn\">924673 -rw-r--r-- 2 root root 1872 /backup/passwd.hardlink</span>\n        <span class=\"out\"># Same inode 924673, link count = 2</span>\n        <span class=\"sec\">──── SYMBOLIC LINK ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ln -s /usr/bin/python3 /usr/local/bin/python</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ls -la /usr/local/bin/python</span></span>\n        <span class=\"ocn\">lrwxrwxrwx 1 root root 16 May 03 /usr/local/bin/python -> /usr/bin/python3</span>\n        <span class=\"sec\">──── DETECT DANGLING SYMLINKS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">find /etc -xtype l 2>/dev/null</span></span>\n        <span class=\"ored\">/etc/alternatives/editor  → dangling symlink!</span>\n        <span class=\"sec\">──── SYMLINK ATTACK DETECTION ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">find /tmp -type l -ls 2>/dev/null</span></span>\n        <span class=\"ored\">lrwxrwxrwx 1 attacker /tmp/evil -> /etc/shadow</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 05 — EXT4 INTERNALS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">💾</span><span class=\"pt\">ext4 Internals — How Linux Stores Data on Disk</span><span class=\"pn\">PANEL 05</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">ext4 Disk Layout</div>\n        <div class=\"ct\">\n          Disk is divided into <span class=\"hl\">block groups</span> (typically 128MB each). Each block group is self-contained with its own superblock copy, block bitmap, inode bitmap, inode table, and data blocks.<br><br>\n          <span class=\"hc\">Superblock</span> — filesystem metadata: block size, inode count, UUID, mount count, journal location.<br><br>\n          <span class=\"hy\">Journal (ext3j)</span> — write-ahead log. Before modifying metadata, writes intent to journal. If power fails mid-write, journal replays and fixes consistency. This is why ext4 survives unclean unmounts.\n        </div>\n      </div>\n      <div class=\"cb cby\">\n        <div class=\"cbt\">ext4 Key Features vs ext3</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.8\">\n          <span class=\"hy\">Extents</span> — contiguous block ranges instead of block pointer arrays. Huge files stored efficiently.<br>\n          <span class=\"hy\">Delayed allocation</span> — holds writes in memory, allocates blocks in batches. Better performance.<br>\n          <span class=\"hy\">Dir indexing</span> — HTree (B-tree) for fast directory lookups even with 100k files.<br>\n          <span class=\"hy\">Checksums</span> — metadata checksums catch silent corruption.<br>\n          <span class=\"hy\">Max file size</span> — 16TB per file. Max FS size: 1EB.\n        </div>\n      </div>\n    </div>\n\n    <!-- ext4 disk layout visual -->\n    <div style=\"background:var(--bg);border:1px solid var(--b2);padding:14px;margin-bottom:14px;overflow-x:auto\">\n      <div style=\"font-family:var(--sans);font-size:10px;letter-spacing:2px;color:var(--t3);text-transform:uppercase;margin-bottom:10px\">ext4 Block Group Layout (simplified)</div>\n      <div style=\"display:flex;gap:3px;min-width:600px;margin-bottom:6px\">\n        <div style=\"background:rgba(255,59,59,.1);border:1px solid rgba(255,59,59,.3);padding:8px 6px;text-align:center;flex:0.5\">\n          <div style=\"font-size:9px;color:var(--r);font-family:var(--sans);font-weight:700\">BOOT<br>SECTOR</div></div>\n        <div style=\"background:rgba(255,215,0,.1);border:1px solid rgba(255,215,0,.3);padding:8px 6px;text-align:center;flex:0.8\">\n          <div style=\"font-size:9px;color:var(--y);font-family:var(--sans);font-weight:700\">SUPER<br>BLOCK</div></div>\n        <div style=\"background:rgba(0,212,255,.08);border:1px solid rgba(0,212,255,.3);padding:8px 6px;text-align:center;flex:0.8\">\n          <div style=\"font-size:9px;color:var(--c);font-family:var(--sans);font-weight:700\">GDT<br>(Group Desc)</div></div>\n        <div style=\"background:rgba(157,78,221,.08);border:1px solid rgba(157,78,221,.3);padding:8px 4px;text-align:center;flex:0.5\">\n          <div style=\"font-size:9px;color:var(--p);font-family:var(--sans);font-weight:700\">BLOCK<br>BITMAP</div></div>\n        <div style=\"background:rgba(157,78,221,.08);border:1px solid rgba(157,78,221,.3);padding:8px 4px;text-align:center;flex:0.5\">\n          <div style=\"font-size:9px;color:var(--p);font-family:var(--sans);font-weight:700\">INODE<br>BITMAP</div></div>\n        <div style=\"background:rgba(0,255,136,.08);border:1px solid rgba(0,255,136,.3);padding:8px 6px;text-align:center;flex:1\">\n          <div style=\"font-size:9px;color:var(--g);font-family:var(--sans);font-weight:700\">INODE<br>TABLE</div></div>\n        <div style=\"background:rgba(41,121,255,.08);border:1px solid rgba(41,121,255,.3);padding:8px 6px;text-align:center;flex:3\">\n          <div style=\"font-size:9px;color:#5599ff;font-family:var(--sans);font-weight:700\">DATA BLOCKS (actual file content)</div></div>\n      </div>\n      <div style=\"font-size:10px;color:var(--t3);font-family:var(--sans)\">↑ Block Group 0 (first 128MB) — pattern repeats for every block group across the partition</div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">ext4 filesystem inspection</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── FILESYSTEM INFO ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">tune2fs -l /dev/nvme0n1p2 | grep -E \"Block|Inode|Journal|UUID|state\"</span></span>\n        <span class=\"ocn\">Filesystem UUID:          a1b2c3d4-e5f6-7890-abcd-ef1234567890</span>\n        <span class=\"out\">Filesystem state:         clean</span>\n        <span class=\"out\">Block count:              15728640</span>\n        <span class=\"out\">Block size:               4096</span>\n        <span class=\"out\">Inode count:              3932160</span>\n        <span class=\"ogn\">Journal inode:            8</span>\n        <span class=\"out\">Journal size:             128M</span>\n        <span class=\"sec\">──── DISK USAGE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">df -hT</span></span>\n        <span class=\"out\">Filesystem     Type   Size  Used Avail Use% Mounted on</span>\n        <span class=\"ocn\">/dev/nvme0n1p2 ext4    60G  12G   46G  21% /</span>\n        <span class=\"out\">tmpfs          tmpfs  7.7G     0  7.7G   0% /dev/shm</span>\n        <span class=\"out\">/dev/nvme0n1p1 vfat   511M  6.1M  505M   2% /boot/efi</span>\n        <span class=\"sec\">──── FIND LARGE FILES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">du -sh /* 2>/dev/null | sort -rh | head -8</span></span>\n        <span class=\"oyn\"> 8.4G  /var</span>\n        <span class=\"oyn\"> 4.2G  /usr</span>\n        <span class=\"out\"> 1.1G  /opt</span>\n        <span class=\"ored\"> 6.8G  /tmp   ← suspicious, investigate</span>\n        <span class=\"sec\">──── FILESYSTEM CHECK ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">fsck -n /dev/sdb1   # dry-run check</span></span>\n        <span class=\"out\">e2fsck 1.47.0: Pass 1: Checking inodes, blocks, and sizes</span>\n        <span class=\"ogn\">Pass 5: Checking group summary information — /dev/sdb1: clean</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 06 — MOUNTING ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔌</span><span class=\"pt\">Mounting — Attaching Filesystems to the Tree</span><span class=\"pn\">PANEL 06</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cbl\">\n        <div class=\"cbt\">What Is Mounting?</div>\n        <div class=\"ct\">\n          Mounting attaches a <span class=\"hl\">filesystem</span> (on a device, network share, or virtual) to a <span class=\"hc\">directory</span> (the mount point) in the existing tree. After mounting, accessing that directory shows the mounted filesystem's contents.<br><br>\n          Unlike Windows (C: D: drives), Linux has <span class=\"hl\">one unified tree</span>. You choose where to attach storage — /data, /mnt/usb, /backup. The underlying device is transparent to applications.\n        </div>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">/etc/fstab — Persistent Mounts</div>\n        <div class=\"ct\" style=\"font-size:12px\">\n          Format: <code style=\"color:var(--c)\">device  mountpoint  fstype  options  dump  pass</code><br><br>\n          <span class=\"hl\">dump</span>: backup (0=no, 1=yes)<br>\n          <span class=\"hl\">pass</span>: fsck order (0=skip, 1=root, 2=others)<br><br>\n          Always use <span class=\"hc\">UUID=</span> not <code>/dev/sdX</code> — device names can change. UUID never changes per partition.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Mounting operations + /etc/fstab</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── MANUAL MOUNT ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mount /dev/sdb1 /mnt/backup</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mount -t nfs 192.168.1.10:/share /mnt/nfs</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mount -o ro,noexec /dev/sdc1 /mnt/evidence  # forensic mount</span></span>\n        <span class=\"sec\">──── /etc/fstab EXAMPLE ────</span>\n        <span class=\"out\"># &lt;device&gt;                                &lt;mount&gt;  &lt;type&gt; &lt;options&gt;            &lt;dump&gt; &lt;pass&gt;</span>\n        <span class=\"ocn\">UUID=a1b2c3d4-e5f6-7890-abcd-ef1234567890  /        ext4   errors=remount-ro   0      1</span>\n        <span class=\"ocn\">UUID=b2c3d4e5-f6a7-8901-bcde-f01234567890  /boot    ext4   defaults            0      2</span>\n        <span class=\"ocn\">UUID=c3d4e5f6-a7b8-9012-cdef-012345678901  /home    ext4   defaults,nodev      0      2</span>\n        <span class=\"oyn\">UUID=d4e5f6a7-b8c9-0123-defa-123456789012  none     swap   sw                  0      0</span>\n        <span class=\"out\">tmpfs                                        /tmp     tmpfs  nodev,nosuid,size=2G 0      0</span>\n        <span class=\"sec\">──── SHOW ALL MOUNTS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">findmnt --real</span></span>\n        <span class=\"out\">TARGET       SOURCE         FSTYPE  OPTIONS</span>\n        <span class=\"ocn\">/            /dev/nvme0n1p2 ext4    rw,relatime</span>\n        <span class=\"out\">├─/boot      /dev/nvme0n1p1 ext4    rw,relatime</span>\n        <span class=\"out\">├─/home      /dev/sdb1      ext4    rw,nodev</span>\n        <span class=\"oyn\">└─/tmp       tmpfs          tmpfs   rw,nodev,nosuid,size=2G</span>\n        <span class=\"sec\">──── SECURE MOUNT OPTIONS (AUDIT) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mount | grep -E \"noexec|nosuid|nodev\"</span></span>\n        <span class=\"ogn\">tmpfs on /tmp type tmpfs (rw,nosuid,nodev,noexec,size=2048M)</span>\n        <span class=\"out\"># noexec = can't run binaries from /tmp (stops many exploits)</span>\n        <span class=\"out\"># nosuid = SUID bits on this FS are ignored</span>\n        <span class=\"out\"># nodev  = device files on this FS are ignored</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 07 — LVM ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">◫</span><span class=\"pt\">LVM — Logical Volume Manager</span><span class=\"pn\">PANEL 07</span></div>\n  <div class=\"pb\">\n    <div class=\"info\"><span style=\"color:var(--c);flex-shrink:0\">ℹ</span><span><strong style=\"color:var(--c)\">LVM</strong> adds an abstraction layer between physical disks and filesystems. Disks are grouped into a <strong>Volume Group (VG)</strong>. VGs are sliced into <strong>Logical Volumes (LVs)</strong> — which act as virtual disks. LVs can be resized live, snapshotted, and spanned across disks without repartitioning.</span></div>\n\n    <!-- LVM layer diagram -->\n    <div style=\"max-width:500px;margin:0 auto 14px\">\n      <div class=\"lvm-layer\" style=\"border-color:rgba(0,255,136,.4);background:rgba(0,255,136,.06)\">\n        <div class=\"lvm-title\" style=\"color:var(--g)\">Filesystems (ext4 / xfs / btrfs)</div>\n        <div class=\"lvm-sub\">formatted and mounted like any partition</div>\n        <div class=\"lvm-chips\"><span class=\"lvm-chip\">/dev/vg0/root (ext4)</span><span class=\"lvm-chip\">/dev/vg0/home (ext4)</span><span class=\"lvm-chip\">/dev/vg0/data (xfs)</span></div>\n      </div>\n      <div class=\"lvm-arrow\">↕ Logical Volumes (LV)</div>\n      <div class=\"lvm-layer\" style=\"border-color:rgba(0,212,255,.4);background:rgba(0,212,255,.06)\">\n        <div class=\"lvm-title\" style=\"color:var(--c)\">Volume Group (VG): vg0 — 240GB total</div>\n        <div class=\"lvm-sub\">pool of physical extents (PEs) — allocation units</div>\n      </div>\n      <div class=\"lvm-arrow\">↕ Physical Volumes (PV)</div>\n      <div class=\"lvm-layer\" style=\"border-color:rgba(255,215,0,.4);background:rgba(255,215,0,.07)\">\n        <div class=\"lvm-title\" style=\"color:var(--y)\">Physical Volumes</div>\n        <div class=\"lvm-sub\">raw disks or partitions initialized for LVM</div>\n        <div class=\"lvm-chips\"><span class=\"lvm-chip\">/dev/nvme0n1p3 (80GB)</span><span class=\"lvm-chip\">/dev/sdb (160GB)</span></div>\n      </div>\n      <div class=\"lvm-arrow\">↕</div>\n      <div class=\"lvm-layer\" style=\"border-color:rgba(255,140,0,.4);background:rgba(255,140,0,.06)\">\n        <div class=\"lvm-title\" style=\"color:var(--o)\">Physical Hardware — NVMe, SSD, HDD, SAN</div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">LVM operations</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── CREATE LVM STACK ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">pvcreate /dev/sdb</span></span>\n        <span class=\"ogn\">  Physical volume \"/dev/sdb\" successfully created.</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">vgcreate vg0 /dev/nvme0n1p3 /dev/sdb</span></span>\n        <span class=\"ogn\">  Volume group \"vg0\" successfully created</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lvcreate -L 50G -n data vg0</span></span>\n        <span class=\"ogn\">  Logical volume \"data\" created.</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mkfs.ext4 /dev/vg0/data && mount /dev/vg0/data /data</span></span>\n        <span class=\"sec\">──── EXTEND VOLUME LIVE (NO DOWNTIME) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lvextend -L +20G /dev/vg0/data</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">resize2fs /dev/vg0/data   # grow ext4 filesystem live</span></span>\n        <span class=\"sec\">──── LVM SNAPSHOT (BACKUP / FORENSICS) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lvcreate -L 5G -s -n data_snap /dev/vg0/data</span></span>\n        <span class=\"ocn\"># Consistent point-in-time snapshot — mount read-only for forensics</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">mount -o ro /dev/vg0/data_snap /mnt/forensics</span></span>\n        <span class=\"sec\">──── VIEW LVM STATE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">pvs && vgs && lvs</span></span>\n        <span class=\"out\">  PV             VG  Fmt  PSize  PFree</span>\n        <span class=\"ocn\">  /dev/nvme0n1p3 vg0 lvm2  80.0g  0g</span>\n        <span class=\"ocn\">  /dev/sdb       vg0 lvm2 160.0g  90g</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 08 — SWAP ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">↔</span><span class=\"pt\">Swap Space — Virtual Memory Extension</span><span class=\"pn\">PANEL 08</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\">\n      <div class=\"cb cbl\">\n        <div class=\"cbt\">What Is Swap?</div>\n        <div class=\"ct\">\n          Swap is disk space used as <span class=\"hl\">overflow RAM</span>. When physical RAM fills up, the kernel's memory manager identifies <span class=\"hc\">least-recently-used pages</span> and moves them to swap (swapping out), freeing RAM for active processes.<br><br>\n          Can be a <span class=\"hy\">swap partition</span> or a <span class=\"hy\">swap file</span>. Swap file is more flexible (resize without repartitioning).<br><br>\n          <span class=\"hr\">Caveat:</span> Swap is 100–1000× slower than RAM. High swap usage = serious performance problem. Check with <code>vmstat 1</code>.\n        </div>\n      </div>\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">Swappiness — Tuning When Swap Triggers</div>\n        <div class=\"ct\" style=\"font-size:12px\">\n          <code>vm.swappiness</code> controls how aggressively kernel swaps:<br><br>\n          <span class=\"hr\">100</span> — swap aggressively (bad for performance)<br>\n          <span class=\"hy\">60</span> — default (swap when RAM ~40% free)<br>\n          <span class=\"hl\">10</span> — prefer to keep things in RAM (production servers)<br>\n          <span class=\"hc\">0</span> — only swap when absolutely necessary<br><br>\n          Recommended for database servers: <span class=\"hl\">vm.swappiness=10</span>\n        </div>\n      </div>\n    </div>\n    <div class=\"term\" style=\"margin-top:14px\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Swap management</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── CREATE SWAP FILE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">fallocate -l 4G /swapfile</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chmod 600 /swapfile && mkswap /swapfile && swapon /swapfile</span></span>\n        <span class=\"sec\">──── SWAP STATISTICS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">vmstat 1 5</span></span>\n        <span class=\"out\">procs ---memory-- ---swap-- ---io-- -system-- -----cpu-----</span>\n        <span class=\"out\"> r  b   swpd  free    si   so   bi    bo  in   cs  us sy id wa</span>\n        <span class=\"ocn\"> 2  0 131072 102400   0    0   12     8  280  520 22  3 74  1</span>\n        <span class=\"ored\"> 1  3 131072  12288 128  256  890   120  420  980 45 12 20 23  ← si/so high = swap thrashing!</span>\n        <span class=\"sec\">──── TUNE SWAPPINESS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">sysctl -w vm.swappiness=10</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">echo \"vm.swappiness=10\" >> /etc/sysctl.d/99-memory.conf</span></span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 09 — LINUX VS WINDOWS FS ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">⇄</span><span class=\"pt\">Linux vs Windows — File System Deep Comparison</span><span class=\"pn\">PANEL 09</span></div>\n  <div class=\"pb\">\n    <table class=\"tbl\">\n      <thead><tr><th>Dimension</th><th>🐧 Linux (ext4/xfs)</th><th>🪟 Windows (NTFS)</th></tr></thead>\n      <tbody>\n        <tr><td>Root structure</td><td style=\"color:var(--t2)\">Single tree rooted at / — everything mounts inside</td><td style=\"color:var(--t2)\">Multiple roots: C:\\, D:\\ — drive letters</td></tr>\n        <tr><td>Path separator</td><td style=\"color:var(--g)\">/  (forward slash)</td><td style=\"color:var(--t2)\">\\  (backslash) — legacy DOS</td></tr>\n        <tr><td>Case sensitivity</td><td style=\"color:var(--g)\">Case-sensitive: file ≠ FILE ≠ File</td><td style=\"color:var(--r)\">Case-insensitive: file = FILE (security risk)</td></tr>\n        <tr><td>Permissions model</td><td style=\"color:var(--t2)\">rwx DAC + ACLs + capabilities + LSM</td><td style=\"color:var(--t2)\">NTFS ACLs (complex SID-based) + UAC</td></tr>\n        <tr><td>Metadata structure</td><td style=\"color:var(--g)\">Inodes (fixed count at mkfs)</td><td style=\"color:var(--t2)\">MFT (Master File Table) — dynamically sized</td></tr>\n        <tr><td>Journal / recovery</td><td style=\"color:var(--g)\">ext4: metadata journal (default) or data journal</td><td style=\"color:var(--g)\">NTFS: $LogFile journal for metadata</td></tr>\n        <tr><td>Max filename length</td><td style=\"color:var(--g)\">255 bytes (UTF-8)</td><td style=\"color:var(--y)\">255 UTF-16 chars</td></tr>\n        <tr><td>Max file size</td><td style=\"color:var(--g)\">ext4: 16TB per file</td><td style=\"color:var(--g)\">NTFS: 16EB theoretical</td></tr>\n        <tr><td>Special files</td><td style=\"color:var(--g)\">Devices, sockets, pipes, symlinks all as \"files\"</td><td style=\"color:var(--t2)\">Separate API for named pipes; devices via registry</td></tr>\n        <tr><td>Virtual FS</td><td style=\"color:var(--g)\">/proc, /sys, /dev — kernel state as files</td><td style=\"color:var(--r)\">Registry (binary hive) — not exposed as files</td></tr>\n        <tr><td>Fragmentation</td><td style=\"color:var(--g)\">Low — ext4 delayed alloc + extents minimize it</td><td style=\"color:var(--y)\">Higher on spinning disks — defrag needed</td></tr>\n        <tr><td>Disk quotas</td><td style=\"color:var(--g)\">Native quota support per user/group</td><td style=\"color:var(--g)\">NTFS disk quotas (less flexible)</td></tr>\n        <tr><td>Encryption</td><td style=\"color:var(--g)\">LUKS (block-level) / fscrypt (per-dir)</td><td style=\"color:var(--g)\">BitLocker (full volume) / EFS (per-file)</td></tr>\n        <tr><td>Network mounts</td><td style=\"color:var(--t2)\">NFS, CIFS/SMB, GlusterFS, FUSE</td><td style=\"color:var(--t2)\">SMB/CIFS, NFS client, DFS</td></tr>\n        <tr><td>Config location</td><td style=\"color:var(--g)\">Plain text files in /etc — version-controllable</td><td style=\"color:var(--r)\">Registry binary hives — not human readable</td></tr>\n      </tbody>\n    </table>\n  </div>\n</div>\n\n<!-- ═══ PANEL 10 — SECURITY ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">🔒</span><span class=\"pt\">Security Perspective — File System Attack Vectors</span><span class=\"pn\">PANEL 10</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\">\n      <div class=\"cb cbr\">\n        <div class=\"cbt\">Red Team — FS Exploits</div>\n        <ul style=\"list-style:none;font-size:12px;color:var(--t2)\">\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span><div><strong style=\"color:var(--r)\">/tmp race condition:</strong> program creates predictable /tmp/tmpXXX file → attacker replaces with symlink to /etc/shadow before program writes → overwrite sensitive file</div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span><div><strong style=\"color:var(--r)\">World-writable /etc file:</strong> chmod 777 /etc/cron.d/ → attacker drops cron job executed as root</div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span><div><strong style=\"color:var(--r)\">SUID binary exploit:</strong> custom SUID binary with command injection → runs as root</div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span><div><strong style=\"color:var(--r)\">/proc/PID/mem:</strong> write to another process's memory space if ptrace_scope=0</div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span><div><strong style=\"color:var(--r)\">Hardlink to SUID:</strong> create hardlink to /usr/bin/sudo → survives if sudo is updated+deleted</div></li>\n          <li style=\"padding:5px 0;display:flex;gap:8px\"><span style=\"color:var(--r)\">›</span><div><strong style=\"color:var(--r)\">Docker volume escape:</strong> mount /:/hostfs in container → access host root FS</div></li>\n        </ul>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">Blue Team — FS Hardening</div>\n        <ul style=\"list-style:none;font-size:12px;color:var(--t2)\">\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span><div>Mount /tmp with <strong>noexec,nosuid,nodev</strong> — prevents executing binaries dropped there</div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span><div>Mount /home with <strong>nodev,nosuid</strong> — users cannot create device files or SUID binaries</div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span><div>File Integrity Monitoring — <strong>AIDE / Tripwire</strong> checksums all critical files, alerts on changes</div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span><div>Audit all SUID/SGID binaries regularly: <code>find / -perm /6000 -type f</code></div></li>\n          <li style=\"padding:5px 0;border-bottom:1px solid var(--b2);display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span><div>chattr +i on critical files: <code>chattr +i /etc/passwd /etc/shadow</code> — immutable flag, even root cannot modify without removing it first</div></li>\n          <li style=\"padding:5px 0;display:flex;gap:8px\"><span style=\"color:var(--g)\">›</span><div>Enable auditd file access rules: watch /etc/shadow, /etc/sudoers for any access</div></li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"term\" style=\"margin-top:12px\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">File system security audit commands</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── WORLD-WRITABLE FILES (HIGH RISK) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">find / -not -path '/proc/*' -not -path '/sys/*' -perm -002 -type f 2>/dev/null</span></span>\n        <span class=\"ored\">/etc/cron.d/backup_job    ← world-writable cron! privilege escalation path</span>\n        <span class=\"sec\">──── FILES WITH NO OWNER (ORPHANED) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">find / -nouser -o -nogroup 2>/dev/null | head -5</span></span>\n        <span class=\"oyn\">/opt/dropped/tool         ← no owner — possible dropped malware</span>\n        <span class=\"sec\">──── IMMUTABLE FLAG (chattr) ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">chattr +i /etc/passwd /etc/shadow /etc/sudoers</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">lsattr /etc/passwd</span></span>\n        <span class=\"ogn\">----i---------e------- /etc/passwd</span>\n        <span class=\"sec\">──── AUDIT RULE — WATCH /etc/shadow ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">auditctl -w /etc/shadow -p rwxa -k shadow_access</span></span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">ausearch -k shadow_access | tail -5</span></span>\n        <span class=\"ored\">type=SYSCALL msg=audit: auid=1001 uid=0 gid=0 comm=\"cat\" exe=\"/bin/cat\" key=\"shadow_access\"</span>\n        <span class=\"sec\">──── AIDE FILE INTEGRITY CHECK ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">aide --check</span></span>\n        <span class=\"ored\">AIDE found differences between database and filesystem!!</span>\n        <span class=\"ored\">Changed: /usr/bin/ls  (SHA256 mismatch — possible binary replacement)</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 11 — MONITORING ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">📊</span><span class=\"pt\">Monitoring &amp; Troubleshooting — Disk &amp; FS Issues</span><span class=\"pn\">PANEL 11</span></div>\n  <div class=\"pb\">\n    <div class=\"g2\" style=\"margin-bottom:14px\">\n      <div class=\"cb cby\">\n        <div class=\"cbt\">Common FS Problems → Diagnosis</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.8\">\n          <span class=\"hy\">Disk full</span> → <code>df -h</code>, <code>du -sh /*</code>, <code>ncdu</code><br>\n          <span class=\"hy\">Inode exhausted</span> → <code>df -i</code>, find dirs with many small files<br>\n          <span class=\"hy\">I/O bottleneck</span> → <code>iostat -x 1</code>, <code>iotop</code><br>\n          <span class=\"hy\">FS corruption</span> → <code>dmesg | grep -i \"ext4\\|error\\|i/o\"</code><br>\n          <span class=\"hy\">Mount failure</span> → <code>journalctl -u systemd-fsck</code><br>\n          <span class=\"hy\">Slow writes</span> → <code>vmstat 1</code> (check wa column)\n        </div>\n      </div>\n      <div class=\"cb cbg\">\n        <div class=\"cbt\">Enterprise Scenario — Disk Full at 3AM</div>\n        <div style=\"font-size:12px;color:var(--t2);line-height:1.7\">\n          1. <code>df -h</code> → /var at 100%<br>\n          2. <code>du -sh /var/* | sort -rh | head</code> → /var/log at 80GB<br>\n          3. <code>ls -lhS /var/log/</code> → nginx access.log is 78GB<br>\n          4. <code>echo \"\" > /var/log/nginx/access.log</code> → immediate relief<br>\n          5. Fix logrotate config + add disk alert at 80%<br>\n          6. <span class=\"hl\">Root cause:</span> logrotate misconfiguration, no size limit\n        </div>\n      </div>\n    </div>\n\n    <div class=\"term\">\n      <div class=\"tbar\"><div class=\"td\" style=\"background:#ff5f57\"></div><div class=\"td\" style=\"background:#febc2e\"></div><div class=\"td\" style=\"background:#28c840\"></div>\n        <span style=\"margin-left:8px;font-size:11px;color:var(--t3);font-family:var(--sans)\">Disk & filesystem monitoring</span></div>\n      <div class=\"tb\">\n        <span class=\"sec\">──── DISK USAGE ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">df -hT && df -i</span></span>\n        <span class=\"sec\">──── I/O STATISTICS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">iostat -x 1 3</span></span>\n        <span class=\"out\">Device    r/s    w/s   rkB/s   wkB/s  await  %util</span>\n        <span class=\"ocn\">nvme0n1  124.0  891.0  4960.0  82944  12.40  98.4  ← 98% busy = I/O saturated!</span>\n        <span class=\"sec\">──── TOP I/O PROCESSES ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">iotop -o -b -n 3</span></span>\n        <span class=\"ored\"> 1234 root   mysqld       85.2 M/s disk write ← MySQL writing heavily</span>\n        <span class=\"sec\">──── KERNEL I/O ERRORS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">dmesg | grep -iE \"error|i/o|ext4|failed\" | tail -6</span></span>\n        <span class=\"ored\">[492011.22] EXT4-fs error (device sdb1): ext4_find_entry: reading directory</span>\n        <span class=\"ored\">[492011.24] Buffer I/O error on dev sdb1, logical block 0, async page read</span>\n        <span class=\"out\"># sdb1 is failing — backup and replace immediately</span>\n        <span class=\"sec\">──── FIND TOP SPACE CONSUMERS ────</span>\n        <span><span class=\"pr\">root@lab:~# </span><span style=\"color:#fff\">du -ahx / 2>/dev/null | sort -rh | head -10</span></span>\n        <span class=\"oyn\"> 8.1G /var/log/nginx/access.log   ← log not rotating!</span>\n        <span class=\"out\"> 4.2G /var/lib/docker</span>\n        <span class=\"out\"> 1.8G /usr</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ═══ PANEL 12 — CHECKLIST ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">✔</span><span class=\"pt\">Auditor / Security Checklist — Step 3 Verification</span><span class=\"pn\">PANEL 12</span></div>\n  <div class=\"pb\">\n    <ul class=\"cl\">\n      <li><div class=\"chk\">✓</div>Can you navigate the FHS and explain the purpose of /etc, /var/log, /proc, /sys, /dev, /tmp?<span class=\"tag tg\" style=\"margin-left:auto\">FHS</span></li>\n      <li><div class=\"chk\">✓</div>Can you explain what an inode is and what it stores (and what it does NOT store)?<span class=\"tag tc\" style=\"margin-left:auto\">INODE</span></li>\n      <li><div class=\"chk\">✓</div>Can you decode any permission string (e.g. -rwsr-xr--) and convert to octal?<span class=\"tag ty\" style=\"margin-left:auto\">PERM</span></li>\n      <li><div class=\"chk\">✓</div>Do you understand the security implication of SUID, SGID, and sticky bit?<span class=\"tag tr2\" style=\"margin-left:auto\">SUID</span></li>\n      <li><div class=\"chk\">✓</div>Can you set up file ACLs with setfacl/getfacl and explain when they're needed?<span class=\"tag tp\" style=\"margin-left:auto\">ACL</span></li>\n      <li><div class=\"chk\">✓</div>Can you explain the difference between hard links and symlinks and their security risks?<span class=\"tag tg\" style=\"margin-left:auto\">LINKS</span></li>\n      <li><div class=\"chk\">✓</div>Do you understand ext4 block groups, the journal, and why fsck matters?<span class=\"tag ty\" style=\"margin-left:auto\">EXT4</span></li>\n      <li><div class=\"chk\">✓</div>Can you write an /etc/fstab entry with secure mount options (noexec, nosuid, nodev)?<span class=\"tag tc\" style=\"margin-left:auto\">FSTAB</span></li>\n      <li><div class=\"chk\">✓</div>Can you create, extend, and snapshot an LVM logical volume?<span class=\"tag to\" style=\"margin-left:auto\">LVM</span></li>\n      <li><div class=\"chk\">✓</div>Can you find world-writable files, orphaned files, and SUID binaries via find?<span class=\"tag tr2\" style=\"margin-left:auto\">AUDIT</span></li>\n      <li><div class=\"chk\">✓</div>Can you use chattr +i to make critical files immutable and verify with lsattr?<span class=\"tag tg\" style=\"margin-left:auto\">HARDEN</span></li>\n      <li><div class=\"chk\">✓</div>Can you diagnose disk-full, inode-exhausted, and I/O bottleneck scenarios?<span class=\"tag ty\" style=\"margin-left:auto\">DEBUG</span></li>\n    </ul>\n  </div>\n</div>\n\n<!-- ═══ PANEL 13 — SUMMARY ═══ -->\n<div class=\"panel\">\n  <div class=\"ph\"><span style=\"font-size:14px\">◉</span><span class=\"pt\">Summary — Step 3 Complete</span><span class=\"pn\">PANEL 13</span></div>\n  <div class=\"pb\">\n    <div class=\"g3\" style=\"margin-bottom:14px\">\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">FHS + Everything is a File</div>\n        <div class=\"sc-v\">One tree rooted at /. /proc and /sys expose kernel state as files. /dev has device files. /etc is the admin's control panel — all plain text, version-control friendly.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">Inodes + Permissions</div>\n        <div class=\"sc-v\">Every object has an inode (metadata only, no name). Permissions: 3×rwx + SUID/SGID/sticky. umask sets defaults. ACLs extend beyond owner/group/other. chattr +i is the last line of defence.</div>\n      </div>\n      <div class=\"sum-card\">\n        <div class=\"sc-l\">ext4 + LVM + Mounting</div>\n        <div class=\"sc-v\">ext4: block groups, extents, journal for consistency. LVM: PV→VG→LV abstraction for live resizing and snapshots. fstab with UUIDs and noexec/nosuid/nodev mount options is baseline hardening.</div>\n      </div>\n    </div>\n    <div class=\"nxt\">\n      <div>\n        <div style=\"font-family:var(--sans);font-weight:600;font-size:14px;color:var(--g)\">▶ Next: Step 4 — User, Permission &amp; Access Control Model</div>\n        <div style=\"font-size:11px;color:var(--t3);margin-top:2px\">Users · groups · root · sudo · PAM · capabilities · privilege escalation · Linux vs Windows permissions</div>\n      </div>\n      <button class=\"nb\" onclick=\"window.sendPrompt && window.sendPrompt('Start Step 4')\">$ Start Step 4 →</button>\n    </div>\n  </div>\n</div>\n\n</div>";

export default function LinuxStep3() {
  return <LessonDocument title="Filesystem Architecture" styles={styles} markup={markup} />;
}
